create or replace function public.leaderboard_sync(p_stars bigint default null, p_include_top boolean default true, p_language text default 'en')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  player uuid := auth.uid();
  result jsonb;
  board_language text := case when lower(split_part(replace(coalesce(p_language, 'en'), '_', '-'), '-', 1)) = 'ru' then 'ru' else 'en' end;
  cis_percentage integer := case when board_language = 'ru' then 60 else 20 end;
begin
  if player is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_include_top is null or (p_stars is not null and (p_stars < 0 or p_stars > 2000000000)) then
    raise exception 'Invalid leaderboard payload' using errcode = '22023';
  end if;
  if p_stars is not null then
    insert into leaderboard_private.players as existing(user_id, stars) values (player, p_stars)
    on conflict (user_id) do update
      set stars = excluded.stars, reached_at = clock_timestamp()
      where excluded.stars > existing.stars;
  end if;
  -- All reads (top and own position) share one statement snapshot.
  with population as (select count(*) as total from leaderboard_private.players), mine as (
    select m.player_id, m.stars, m.reached_at,
      1 + (select count(*) from leaderboard_private.players p
        where p.stars > m.stars
          or (p.stars = m.stars and (p.reached_at, p.player_id) < (m.reached_at, m.player_id))) as rank
    from leaderboard_private.players m where m.user_id = player
  ), top_players as (
    select p.player_id, p.stars, p.reached_at, p.user_id = player as is_me
    from leaderboard_private.players p where p_include_top
    order by p.stars desc, p.reached_at, p.player_id limit 100
  ), ranked_top as (
    select player_id, stars, is_me,
      row_number() over (order by stars desc, reached_at, player_id) as rank
    from top_players
  ), filler_quotas as (
    select 100-count(*) as missing, ((100-count(*))*cis_percentage+50)/100 as cis_count from top_players
  ), scored_fillers as (
    -- Stable pseudorandom sampling for one account, independent of JWT rotation.
    select f.*, row_number() over (partition by f.pool
      order by md5('pick:v2:' || player::text || ':' || f.pool || ':' || f.slot::text), f.slot) as pool_rank,
      md5('order:v2:' || player::text || ':' || f.pool || ':' || f.slot::text) as display_order
    from leaderboard_private.fillers f where p_include_top
  ), chosen_fillers as (
    select f.* from scored_fillers f cross join filler_quotas q
    where f.pool_rank <= case when f.pool='cis' then q.cis_count else q.missing-q.cis_count end
  ), filler_rows as (
    select 'filler:' || f.pool || ':' || lpad(f.slot::text, 3, '0') as player_id,
      f.nickname, 0::bigint as stars, false as is_me, true as is_filler,
      (select count(*) from top_players) + row_number() over (order by f.display_order, f.pool, f.slot) as rank
    from chosen_fillers f
  ), display_top as (
    select player_id::text as player_id,
      (case when board_language = 'ru' then 'Игрок ' else 'Player ' end) || player_id::text as nickname,
      stars, is_me, false as is_filler, rank from ranked_top
    union all
    select player_id, nickname, stars, is_me, is_filler, rank from filler_rows
  )
  select jsonb_build_object('ok', true, 'language', board_language, 'total_players', (select total from population), 'me',
    (select jsonb_build_object('player_id', player_id::text,
      'nickname', (case when board_language = 'ru' then 'Игрок ' else 'Player ' end) || player_id::text,
      'is_filler', false, 'stars', stars,
      'rank', case when rank <= 100 then rank else null end,
      'top_percent', case when rank > 100 then
        ceil(100::numeric * rank / (select total from population))::integer else null end) from mine))
    || case when p_include_top then jsonb_build_object('top',
      coalesce((select jsonb_agg(jsonb_build_object(
        'player_id', player_id, 'nickname', nickname, 'stars', stars, 'rank', rank, 'is_me', is_me, 'is_filler', is_filler) order by rank)
        from display_top), '[]'::jsonb)) else '{}'::jsonb end
    into result;
  return result;
end;
$$;
revoke all on function public.leaderboard_sync(bigint, boolean, text) from public, anon;
grant execute on function public.leaderboard_sync(bigint, boolean, text) to authenticated;

create or replace function public.leaderboard_sync_dev(p_stars bigint default null, p_include_top boolean default true, p_language text default 'en')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  player uuid := auth.uid();
  result jsonb;
  board_language text := case when lower(split_part(replace(coalesce(p_language, 'en'), '_', '-'), '-', 1)) = 'ru' then 'ru' else 'en' end;
  cis_percentage integer := case when board_language = 'ru' then 60 else 20 end;
begin
  if player is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_include_top is null or (p_stars is not null and (p_stars < 0 or p_stars > 2000000000)) then
    raise exception 'Invalid leaderboard payload' using errcode = '22023';
  end if;
  if p_stars is not null then
    insert into leaderboard_dev_private.players as existing(user_id, stars) values (player, p_stars)
    on conflict (user_id) do update
      set stars = excluded.stars, reached_at = clock_timestamp()
      where excluded.stars > existing.stars;
  end if;
  -- All reads (top and own position) share one statement snapshot.
  with population as (select count(*) as total from leaderboard_dev_private.players), mine as (
    select m.player_id, m.stars, m.reached_at,
      1 + (select count(*) from leaderboard_dev_private.players p
        where p.stars > m.stars
          or (p.stars = m.stars and (p.reached_at, p.player_id) < (m.reached_at, m.player_id))) as rank
    from leaderboard_dev_private.players m where m.user_id = player
  ), top_players as (
    select p.player_id, p.stars, p.reached_at, p.user_id = player as is_me
    from leaderboard_dev_private.players p where p_include_top
    order by p.stars desc, p.reached_at, p.player_id limit 100
  ), ranked_top as (
    select player_id, stars, is_me,
      row_number() over (order by stars desc, reached_at, player_id) as rank
    from top_players
  ), filler_quotas as (
    select 100-count(*) as missing, ((100-count(*))*cis_percentage+50)/100 as cis_count from top_players
  ), scored_fillers as (
    -- Stable pseudorandom sampling for one account, independent of JWT rotation.
    select f.*, row_number() over (partition by f.pool
      order by md5('pick:v2:' || player::text || ':' || f.pool || ':' || f.slot::text), f.slot) as pool_rank,
      md5('order:v2:' || player::text || ':' || f.pool || ':' || f.slot::text) as display_order
    from leaderboard_dev_private.fillers f where p_include_top
  ), chosen_fillers as (
    select f.* from scored_fillers f cross join filler_quotas q
    where f.pool_rank <= case when f.pool='cis' then q.cis_count else q.missing-q.cis_count end
  ), filler_rows as (
    select 'filler:' || f.pool || ':' || lpad(f.slot::text, 3, '0') as player_id,
      f.nickname, 0::bigint as stars, false as is_me, true as is_filler,
      (select count(*) from top_players) + row_number() over (order by f.display_order, f.pool, f.slot) as rank
    from chosen_fillers f
  ), display_top as (
    select player_id::text as player_id,
      (case when board_language = 'ru' then 'Игрок ' else 'Player ' end) || player_id::text as nickname,
      stars, is_me, false as is_filler, rank from ranked_top
    union all
    select player_id, nickname, stars, is_me, is_filler, rank from filler_rows
  )
  select jsonb_build_object('ok', true, 'language', board_language, 'total_players', (select total from population), 'me',
    (select jsonb_build_object('player_id', player_id::text,
      'nickname', (case when board_language = 'ru' then 'Игрок ' else 'Player ' end) || player_id::text,
      'is_filler', false, 'stars', stars,
      'rank', case when rank <= 100 then rank else null end,
      'top_percent', case when rank > 100 then
        ceil(100::numeric * rank / (select total from population))::integer else null end) from mine))
    || case when p_include_top then jsonb_build_object('top',
      coalesce((select jsonb_agg(jsonb_build_object(
        'player_id', player_id, 'nickname', nickname, 'stars', stars, 'rank', rank, 'is_me', is_me, 'is_filler', is_filler) order by rank)
        from display_top), '[]'::jsonb)) else '{}'::jsonb end
    into result;
  return result;
end;
$$;
revoke all on function public.leaderboard_sync_dev(bigint, boolean, text) from public, anon;
grant execute on function public.leaderboard_sync_dev(bigint, boolean, text) to authenticated;

